let type = 'error';

if (typeof result === 'number') {
    if (result >= 200 && result < 300) type = 'success';
    else if (result >= 400 && result < 500) type = 'warning';
    else if (result >= 500) type = 'error';
    else type = 'info';

} else if (typeof result === 'string') {
    const upperResult = result.toUpperCase();
    if (['OK', 'SUCCESS'].includes(upperResult)) type = 'success';
    else if (['WARNING', 'PARTIAL CONTENT'].includes(upperResult)) type = 'warning';
    else if (upperResult === 'INFO') type = 'info';
    else type = 'error';
}

switch (type) {
    case 'success':
        // this.$notificationManager.show(message, {
        //     delay: 3500,
        //     icon: 'check',
        //     color: 'success',
        //     dismissible: true,
        //     animation: 'fade'
        // });
        break;

    case 'info':
        this.$notificationManager.show(message, {
            delay: 3500,
            icon: 'info-circle',
            color: 'primary',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case 'warning':
        this.$notificationManager.show(message, {
            delay: 3500,
            icon: 'exclamation-triangle',
            color: 'warning',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case 'error':
    default:
        this.$notificationManager.show(message, {
            delay: 5000,
            icon: 'exclamation-circle',
            color: 'danger',
            dismissible: true,
            animation: 'fade'
        });
        break;
}

for (let prop in form) {
    if (form.hasOwnProperty(prop)) {
        form[prop] = undefined;
    }
}

if (Array.isArray(arrayOfVariables)) {
    arrayOfVariables.forEach(variable => {
        if (Array.isArray(ctrl[variable])) ctrl[variable].length = 0;
        else if (typeof ctrl[variable] === "string" && ctrl[variable]) ctrl[variable] = "";
        else if (ctrl[variable]) ctrl[variable] = undefined;
    });
}

if (!input) return null;
const date = new Date(input);

if (isNaN(date.getTime())) {
    console.warn("Invalid date passed to formatDate:", input);
    return null;
}

const pad = (num, size) => String(num).padStart(size, '0');
const year = date.getFullYear();
const month = pad(date.getMonth() + 1, 2);
const day = pad(date.getDate(), 2);

return `${year}-${month}-${day} 00:00:00.000`;

