if (!controller) return null;

const formValidationMap = this.formValidation.getFormValidationMap();

let activeForm = null;
let activeConfig = null;
let tabConfig = null;

if (!uiState) {
    uiState = controller.uiState;
}

const uiStateCurrentTabName = uiState?.currentTab?.name;

if (uiStateCurrentTabName) {
    // Refactor: Handle snake_case or standard names
    // e.g., 'pay_schedule' -> ['pay', 'schedule'] -> 'PaySchedule'
    // e.g., 'company' -> ['company'] -> 'Company'
    const normalizedTabName = uiStateCurrentTabName
        .split('_')
        .map(part => part.charAt(0).toUpperCase() + part.slice(1))
        .join('');

    tabConfig = formValidationMap[normalizedTabName];

    // Only proceed if we found a matching config in the map
    if (tabConfig) {
        activeForm = controller[tabConfig.formKey];
        activeConfig = tabConfig.config;
    }
}

// Fallback: If no tab name was found or the tab name didn't match a config,
// check the boolean flags (e.g., isAddingCompany).
if (!activeForm || !activeConfig) {
    for (const tabName in formValidationMap) {
        const flagName = `isAdding${tabName}`;
        if (controller[flagName]) {
            tabConfig = formValidationMap[tabName];
            activeForm = controller[tabConfig.formKey];
            activeConfig = tabConfig.config;
            break;
        }
    }
}

if (!activeForm || !activeConfig) {
    return null;
}

return this.formValidation.generateMissingFieldsMessage({
    form: activeForm,
    requiredFieldsConfig: activeConfig,
    context: controller
});

const { form, requiredFieldsConfig, context = {} } = options;

if (!form || !Array.isArray(requiredFieldsConfig)) {
    return null;
}

const missingFieldLabels = [];

for (const field of requiredFieldsConfig) {
    let isRequired = true;
    if (typeof field.condition === 'function') {
        isRequired = field.condition(form, context);
    }

    if (!isRequired) {
        continue;
    }

    const value = form[field.key];
    let isInvalid = false;

    if (typeof field.isValid === 'function') {
        isInvalid = !field.isValid(value, form);
    } else {
        isInvalid = (value === null || value === undefined || String(value).trim() === '');
    }

    if (isInvalid) {
        missingFieldLabels.push(field.label);
    }
}

if (missingFieldLabels.length > 0) {
    return `Missing required fields:\n${missingFieldLabels.join('\n')}`;
}

return null;

