if (!value) return "N/A";

// This is the internationalization API for relative time. 'en' is for English.
// 'numeric: "auto"' allows it to use words like "yesterday" or "tomorrow".
const rtf = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });

try {
    const expirationDate = new Date(value);
    const now = new Date();

    // Handle invalid date strings
    if (isNaN(expirationDate.getTime())) {
        return "Invalid date";
    }

    // Find the difference in seconds
    const diffSeconds = Math.round((expirationDate.getTime() - now.getTime()) / 1000);

    // Determine the best unit to display
    if (Math.abs(diffSeconds) < 60) {
        return rtf.format(diffSeconds, 'second');
    }

    const diffMinutes = Math.round(diffSeconds / 60);
    if (Math.abs(diffMinutes) < 60) {
        return rtf.format(diffMinutes, 'minute');
    }

    const diffHours = Math.round(diffMinutes / 60);
    if (Math.abs(diffHours) < 24) {
        return rtf.format(diffHours, 'hour');
    }

    const diffDays = Math.round(diffHours / 24);
    return rtf.format(diffDays, 'day');

} catch (error) {
    console.error("Error formatting time remaining:", error);
    return "Invalid date";
}

if (!word) return "";

if (word.endsWith('y') && !/[aeiou]y$/i.test(word)) {
    return word.slice(0, -1) + 'ies';
}

if (/(s|x|z|ch|sh)$/i.test(word)) {
    return word + 'es';
}

return word + 's';

const { columnKeys = [], options = {} } = params;

return columnKeys.map(key => {
    const readableName = key
        .replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/([A-Z])([A-Z][a-z])/g, '$1 $2')
        .trim();

    const valueKey = options.valueKey && options.valueKey[key] ? options.valueKey[key] : key;

    return {
        name: readableName,
        valueKey: valueKey, 
        hide: options.hide !== undefined ? options.hide : false,
        textAlign: options.textAlign !== undefined ? options.textAlign : "left",
        enableSorting: options.enableSorting !== undefined ? options.enableSorting : false,
        sortBy: options.sortBy !== undefined ? options.sortBy : "none",
        enableFiltering: options.enableFiltering !== undefined ? options.enableFiltering : false,
        enablePinning: options.enablePinning !== undefined ? options.enablePinning : false,
        type: (options.type && options.type[key]) ? options.type[key] : "string",
        cellTemplate: options.cellTemplate !== undefined ? options.cellTemplate[key] : "default",
        cellTooltip: options.cellTooltip !== undefined ? options.cellTooltip : '',
        cellConditionalStyle: options.cellConditionalStyle !== undefined ? options.cellConditionalStyle : [],
        cellActions: options.cellActions !== undefined ? options.cellActions : [],
        classes: options.classes !== undefined ? options.classes : [],
        conditionalClasses: options.conditionalClasses !== undefined ? options.conditionalClasses : [],
        cellTemplateJsExpression: options.cellTemplateJsExpression !== undefined ? options.cellTemplateJsExpression[key] : ""
    };
});

if (!Array.isArray(data) || !data.length) return [];
if (!keysToConvert || !keysToConvert.length) return data;

return data.map(item => {
    const newItem = { ...item };

    keysToConvert.forEach(key => {
        if (Object.prototype.hasOwnProperty.call(newItem, key)) {
            const val = newItem[key];
            newItem[key] = (val === 1 || val === "1" || val === true || val === "true");
        }
    });

    return newItem;
});

if (!defs || !defs.options || !defs.options.type) return [];

const booleanCols = Object.keys(defs.options.type)
    .filter(key => defs.options.type[key] === 'boolean');

return booleanCols.map(colName => {
    const mappedKey = defs.options.valueKey && defs.options.valueKey[colName];
    return mappedKey || colName;
});

const { entity, utils } = params;

let entityDetails = "";

for (const [key, value] of Object.entries(entity)) {
    if (key.startsWith("$$")) continue;
    if (key.includes("Company")) continue;
    if (key.includes("YesNo")) continue;
    if ((key.includes("Id") && key !== "Id") || value === undefined) continue;
    if (key === "CreatedDate" || key === "AnnualPayPeriods") entityDetails += `<br><hr>`;

    if (key.includes("CalculationMethodId")) {
        entityDetails +=
            `
            <div style="display: flex; width: 100%;">
                <div style="font-weight: bold;">${key}</div>
                <div style="flex-grow: 1;"></div>
                <div>${value === 1 ? "FLAT" : "PERCENT"}</div>
            </div>
            <hr>
            `;
        continue;
    }

    if (typeof value === "boolean") {
        entityDetails +=
            `
            <div style="display: flex; width: 100%; align-items: center;">
                <div style="font-weight: bold; flex-shrink: 0;">${key}</div>
                <div style="flex-grow: 1;"></div>
                <div class="status-indicator ${value ? 'yes' : 'no'}">
                    ${value ? 'YES' : 'NO'}
                </div>
            </div>
            <hr>
            `;
        continue;
    }

    entityDetails +=
        `
        <div style="display: flex; width: 100%;">
            <div style="font-weight: bold;">${key}</div>
            <div style="flex-grow: 1;"></div>
            <div>${typeof key === "string" && key.includes("Date") ? utils.parseDate(value) : value}</div>
        </div>
        <hr>
        `;

    if (key === "DayStartTime") entityDetails += `<br>`;
}

return entityDetails;

const pascalCased = Object.fromEntries(
